def price_order(items, customer_tier, coupon=None):
    subtotal = 0.0
    for item in items:
        price = item["price"]
        qty = item["qty"]
        if qty <= 0:
            raise ValueError("quantity must be positive")
        if item.get("sale"):
            price = price * 0.9
        if qty >= 10:
            price = price * 0.95
        subtotal += price * qty
    discount = 0.0
    if customer_tier == "gold":
        discount = 0.10
    elif customer_tier == "silver":
        discount = 0.05
    elif customer_tier == "bronze":
        discount = 0.02
    if coupon == "SAVE5":
        discount += 0.05
    elif coupon == "SAVE10":
        discount += 0.10
    elif coupon is not None:
        raise ValueError(f"unknown coupon: {coupon}")
    discount = min(discount, 0.25)
    total = subtotal * (1 - discount)
    if total > 500:
        shipping = 0.0
    elif total > 100:
        shipping = 5.0
    else:
        shipping = 10.0
    return round(total + shipping, 2)

