import pytest

from orders.pricing import price_order


def test_plain_order():
    assert price_order([{"price": 20.0, "qty": 2}], "none") == 50.0


def test_gold_with_coupon():
    items = [{"price": 100.0, "qty": 2}]
    assert price_order(items, "gold", "SAVE5") == 175.0


def test_bad_quantity():
    with pytest.raises(ValueError, match="positive"):
        price_order([{"price": 1.0, "qty": 0}], "none")
